				return
			}
			t.Cleanup(func() {
				err := expFunc(context.Background())
				assert.NoError(t, err)
			})
			assert.NoError(t, err)
			assert.NotNil(t, exp)
			assert.NotNil(t, expFunc)

		})
	}
}

func TestNewGRPCServer(t *testing.T) {
	tmp := t.TempDir()
	cfg := &config.Config{}
	cfg.Database.URL = fmt.Sprintf("file:%s", filepath.Join(tmp, "flipt.db"))
